/* Auto-generated by 4_myot_build_site.py - offline support.
   The first visit downloads every page, so the whole site keeps working
   offline in that browser. Online, pages always load fresh from the network. */
const CACHE = 'myot-202611070044UTC';
const PRECACHE = ["./", "index.html", "daily.html", "rf.html", "pm.html", "apu.html", "ft.html", "insights.html", "assets/style.css", "assets/charts.js", "data/site_data.js", "favicon.ico", "https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE)
    .then(c => Promise.all(PRECACHE.map(u => c.add(u).catch(() => null))))
    .then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('myot-') && k !== CACHE)
                                  .map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// Network first (fresh data when online), cache when offline.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  e.respondWith(
    fetch(e.request).then(resp => {
      if (resp && (resp.ok || resp.type === 'opaque')) {
        const copy = resp.clone();
        caches.open(CACHE).then(c => c.put(e.request, copy));
      }
      return resp;
    }).catch(() => caches.match(e.request, { ignoreSearch: true }))
  );
});
